window.ANUARUS_RAW_LOGO = 'data:image/jpeg;base64,';

(function() {
  window.ANUARUS_TRANSPARENT_LOGO = window.ANUARUS_RAW_LOGO;
  const callbacks = [];
  let processed = false;

  window.onAnuarusLogoReady = function(cb) {
    if (processed) {
      cb(window.ANUARUS_TRANSPARENT_LOGO);
    } else {
      callbacks.push(cb);
    }
  };

  function processLogo() {
    const img = new Image();
    img.onload = function() {
      try {
        const w = img.naturalWidth || img.width;
        const h = img.naturalHeight || img.height;
        const canvas = document.createElement('canvas');
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0);
        const imgData = ctx.getImageData(0, 0, w, h);
        const data = imgData.data;
        const visited = new Uint8Array(w * h);
        const queue = new Int32Array(w * h);
        let head = 0, tail = 0;

        function isBg(idx) {
          const p = idx * 4;
          const r = data[p], g = data[p + 1], b = data[p + 2];
          const lum = (r + g + b) / 3;
          return lum > 212;
        }

        function enqueue(x, y) {
          if (x < 0 || x >= w || y < 0 || y >= h) return;
          const idx = y * w + x;
          if (visited[idx]) return;
          if (isBg(idx)) {
            visited[idx] = 1;
            queue[tail++] = idx;
          }
        }

        // Seed from top, left, right edges and bottom corners (exterior of coat)
        for (let x = 0; x < w; x++) {
          enqueue(x, 0);
          if (x < 65 || x > w - 65) enqueue(x, h - 1);
        }
        for (let y = 0; y < h; y++) {
          enqueue(0, y);
          enqueue(w - 1, y);
        }

        while (head < tail) {
          const idx = queue[head++];
          const x = idx % w;
          const y = (idx / w) | 0;
          const p = idx * 4;
          data[p + 3] = 0; // Transparent

          // Check 4 neighbors
          if (x > 0) enqueue(x - 1, y);
          if (x < w - 1) enqueue(x + 1, y);
          if (y > 0) enqueue(x, y - 1);
          if (y < h - 1) enqueue(x, y + 1);
        }

        // Anti-alias fringe pixels adjacent to transparent exterior
        for (let y = 1; y < h - 1; y++) {
          for (let x = 1; x < w - 1; x++) {
            const idx = y * w + x;
            if (!visited[idx]) {
              const hasBgNeighbor =
                visited[idx - 1] || visited[idx + 1] || visited[idx - w] || visited[idx + w];
              if (hasBgNeighbor) {
                const p = idx * 4;
                const lum = (data[p] + data[p + 1] + data[p + 2]) / 3;
                if (lum > 155) {
                  const alpha = Math.max(0, Math.min(255, Math.round((225 - lum) * 3.5)));
                  data[p + 3] = alpha;
                }
              }
            }
          }
        }

        ctx.putImageData(imgData, 0, 0);
        window.ANUARUS_TRANSPARENT_LOGO = canvas.toDataURL('image/png');
      } catch (e) {
        console.warn('Logo transparency processing fallback:', e);
      }
      processed = true;
      document.querySelectorAll('img[data-anuarus-logo]').forEach(el => {
        el.src = window.ANUARUS_TRANSPARENT_LOGO;
      });
      callbacks.forEach(cb => cb(window.ANUARUS_TRANSPARENT_LOGO));
    };
    img.src = window.ANUARUS_RAW_LOGO;
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', processLogo);
  } else {
    processLogo();
  }
})();
